import {ROLES,NURSERIES,VERSION,uid,emptyState,demoState,lotBy,locBy,total,physical,reserved,held,remaining,freeFor,availablePosition,ticketText} from './model.mjs';
import {openStore,readState,runCommand,replaceState} from './store.mjs';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=n=>new Intl.NumberFormat('es-CL').format(n||0);const date=d=>new Date(d).toLocaleString('es-CL',{dateStyle:'short',timeStyle:'short'});
const paths={leaf:'M12 21v-9M12 16C4 16 3 10 3 4c6 0 10 4 9 12Zm0-5c0-7 5-9 9-8 0 5-3 8-9 8Z',home:'m3 10 9-7 9 7v10H3Z M9 20v-7h6v7',box:'m3 7 9-4 9 4-9 4ZM3 7v10l9 4 9-4V7M12 11v10',move:'M3 7h17m-5-5 5 5-5 5M21 17H4m5-5-5 5 5 5',truck:'M3 6h11v11H3ZM14 10h4l3 4v3h-7M8 18a2 2 0 1 1-4 0 2 2 0 1 1 4 0m12 0a2 2 0 1 1-4 0 2 2 0 1 1 4 0',check:'M9 3h6v4H9ZM7 5H4v16h16V5h-3M8 14l3 3 5-6',history:'M3 12a9 9 0 1 1 3 7M3 4v7h7M12 7v5l4 3',settings:'M4 7h16M4 17h16M8 3v8M16 13v8',plus:'M12 4v16M4 12h16',arrow:'M5 12h14m-5-5 5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',pin:'M12 22s8-7 8-14a8 8 0 0 0-16 0c0 7 8 14 8 14ZM15 8a3 3 0 1 1-6 0 3 3 0 1 1 6 0',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6ZM8 12l3 3 5-6',qr:'M3 3h6v6H3ZM15 3h6v6h-6ZM3 15h6v6H3ZM15 15h3v3h3v3h-6ZM12 3v7M3 12h9v9M18 12h3',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 1 1 16 0',menu:'M3 6h18M3 12h18M3 18h18',file:'M5 2h9l5 5v15H5ZM14 2v6h5M8 13h8M8 17h6',alert:'m12 3 10 18H2ZM12 9v5M12 17v1'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`}
function button(label,action,args='',kind=''){return `<button class="button ${kind}" data-action="${action}" data-id="${h(args)}">${h(label)}</button>`}
const stateLabels={available:'Habilitado',blocked:'Bloqueo preventivo',inspection:'Inspección ITO',quarantine:'Cuarentena',rejected:'Rechazado',transit:'En tránsito',custody:'Custodia EECC',pending:'Pendiente',approved:'Autorizado',delivered:'Entregado',closed:'Cerrado',partial:'Recepción parcial'};
function badge(label,kind=''){return `<span class="badge ${kind}">${h(stateLabels[label]||label)}</span>`}
let scanner; let state,view='home',filter='',quality='',nursery='',status='',actor={name:'Responsable de prueba',role:ROLES[0],nursery:'VMA'},channel;
try{actor={...actor,...JSON.parse(localStorage.getItem('sitrap21-actor')||'{}')}}catch{}
const menus=[['home','home','Resumen'],['inventory','box','Inventario'],['orders','check','Pedidos y despachos'],['transfers','truck','Traslados'],['inspections','shield','Inspección y calidad'],['returns','move','Devoluciones'],['locations','pin','Ubicaciones'],['scan','qr','Escanear QR'],['history','history','Historial'],['settings','settings','Guía de pruebas']];
const titles=Object.fromEntries(menus.map(([id,,label])=>[id,label]));
function nav(v){if(scanner){scanner.clear().catch(()=>{});scanner=null;}view=v;filter='';quality='';nursery='';status='';render();window.scrollTo(0,0)}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function shell(body){return `<div class="shell"><div class="mobile-mask" data-action="menu"></div><aside class="sidebar"><div class="brand"><img src="./icon.svg" alt=""><div><b>SITRAP</b><small>TRAZABILIDAD DE PLANTAS</small></div></div><div class="nav-label">Espacio de trabajo</div><nav class="nav">${menus.map(([id,ic,label])=>`<button data-nav="${id}" class="${view===id?'active':''}">${icon(ic)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="version">VERSIÓN 2.1 · PILOTO</span><p>Crecer con trazabilidad.</p><small>Pruebas locales · datos ficticios<br>Operación objetivo: enero 2027</small></div></aside><main class="main"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="Abrir menú">${icon('menu')}</button><div class="breadcrumb">Viveros MLP <span>/</span><strong>${titles[view]}</strong></div><div class="top-actions"><span class="connection ${navigator.onLine?'':'off'}"><i class="dot"></i>${navigator.onLine?'Con conexión':'Sin conexión'} · guardado local</span><button class="profile" data-action="profile"><span class="avatar">${h(actor.name.split(' ').map(v=>v[0]).slice(0,2).join(''))}</span><span class="name">${h(actor.name)}<small>${h(actor.role)} · ${actor.nursery}</small></span></button></div></header><div class="content"><div class="pilot-note">${icon('alert').replace('<svg ','<svg style="width:15px;min-width:15px" ')}<span><b>Entorno de pruebas.</b> Datos solo en este dispositivo. Roles simulados; sin sincronización ni acceso a la BD real.</span><button data-nav="settings">Ver alcance</button></div>${body}<footer class="footer"><span>SITRAP 2.1 · Sistema de Trazabilidad de Plantas</span><span>Guardado en este dispositivo · ${state.events.length} registros</span></footer></div></main></div>`}
function heading(title,desc,action=''){return `<div class="heading"><div><p class="eyebrow">CONTROL OPERACIONAL · ${h(NURSERIES[actor.nursery])}</p><h1>${title}</h1><p class="subtitle">${desc}</p></div>${action}</div>`}
function stat(label,value,sub,ic,featured=false){return `<div class="stat ${featured?'featured':''}"><div class="label">${label}${icon(ic)}</div><div class="value">${num(value)}</div><small>${sub}</small></div>`}
function empty(title,desc,action=''){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${desc}</p>${action}</div>`}
function qualityTotal(q,n=''){return state.positions.filter(p=>p.status!=='custody'&&lotBy(state,p.lot).quality===q&&(!n||p.nursery===n)&&p.status!=='transit').reduce((s,p)=>s+p.qty,0)}
function listEvents(events){return `<div class="timeline">${events.slice().reverse().slice(0,view==='history'?150:5).map(e=>`<div class="timeline-item"><span class="timeline-mark"></span><div><b>${h(e.type)}</b><p>${h(e.actor)} · ${h(e.role)}</p><button class="text-link" data-action="event" data-id="${e.id}">Ver respaldo</button></div><time>${date(e.at)}</time></div>`).join('')||empty('Sin movimientos todavía','Cada operación confirmada aparecerá aquí con su responsable.')}</div>`}
function home(){const pending=state.positions.filter(p=>p.qty>0&&p.status==='inspection').length;const orders=state.orders.filter(o=>o.status==='approved');const available=state.lots.filter(l=>l.quality==='C1').reduce((sum,l)=>sum,0);const keys=new Set(state.lots.filter(l=>l.quality==='C1').map(l=>l.species));const ready=Object.keys(NURSERIES).reduce((n,v)=>n+[...keys].reduce((a,sp)=>a+freeFor(state,sp,'C1',v),0),0);return heading('Tu vivero, en una mirada','Existencias, compromisos y tareas para comenzar el día.',`<button class="button primary" data-action="high">${icon('plus')} Registrar alta</button>`)+(!state.events.length?`<div class="intro"><div><p class="eyebrow" style="color:#c1d69c">BIENVENIDO A SITRAP 2.1</p><h2>Un espacio para probar en terreno.</h2><p>Comienza con un escenario ficticio: seis especies, tres viveros y un pedido para practicar. También puedes iniciar tus propios lotes de prueba.</p></div><div class="buttons">${button('Cargar ejemplo guiado','demo','','light')}${button('Ver guía','guide')}</div></div>`:'')+`<div class="stats">${stat('Inventario general',total(state),'Incluye tránsito · excluye custodia','leaf',true)}${stat('C1 disponible',ready,'Habilitado y sin reservas','box')}${stat('Plantas comprometidas',reserved(state),'Saldo de pedidos autorizados','check')}${stat('En tránsito',state.positions.filter(p=>p.status==='transit').reduce((a,p)=>a+p.qty,0),'Pendientes de recepción','truck')}</div><div class="quick">${[['high','plus','Registrar alta','Nuevo ingreso C3'],['operation','move','Mover plantas','Ubicación, calidad y bajas'],['order','check','Nuevo pedido','Reserva y preparación'],['transfer','truck','Crear traslado','Salida a otro vivero']].map(([a,ic,t,d])=>`<button data-action="${a}">${icon(ic)}<span><b>${t}</b><small>${d}</small></span></button>`).join('')}</div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Existencias por vivero</h2><p>Distribución física por calidad · no incluye tránsito ni custodia</p></div><button class="text-link" data-nav="inventory">Ver inventario ↗</button></div><div class="card-body">${Object.entries(NURSERIES).map(([id,name])=>{const vals=['C1','C2','C3'].map(q=>qualityTotal(q,id));const max=Math.max(1,...Object.keys(NURSERIES).map(n=>physical(state,n)));return `<div class="bar-row"><span>${name}</span><div class="bar">${vals.map((v,i)=>`<span class="c${i+1}" style="width:${v/max*100}%" title="C${i+1}: ${v}"></span>`).join('')}</div><b class="num">${num(physical(state,id))}</b></div>`}).join('')}<div class="legend"><span><i class="c1"></i>C1 · Apta para entrega</span><span><i class="c2"></i>C2 · Acondicionamiento</span><span><i class="c3"></i>C3 · No disponible</span></div></div></section><section class="card"><div class="card-head"><div><h2>Tu próxima acción</h2><p>Prioridades de operación</p></div>${badge('Hoy','gray')}</div><div class="card-body tasks">${[['orders','check','Pedidos por preparar','Asignar lotes y confirmar entregas',orders.length],['inspections','shield','Recepciones por evaluar','Control de calidad del Supervisor ITO',pending],['returns','move','Devoluciones pendientes','Custodia y evaluación técnica',state.returns.filter(r=>r.status!=='closed').length]].map(([v,ic,t,d,n])=>`<div class="task"><div class="task-icon">${icon(ic)}</div><span><b>${t}</b><small>${d}</small></span><strong>${n}</strong><button class="text-link" data-nav="${v}" aria-label="Abrir ${t}">→</button></div>`).join('')}</div></section></div><section class="card"><div class="card-head"><div><h2>Últimos movimientos</h2><p>Un historial para cada cambio</p></div><button class="text-link" data-nav="history">Ver historial ↗</button></div>${listEvents(state.events)}</section>`}
function inventory(){const rows=state.positions.filter(p=>p.qty>0&&p.status!=='custody').filter(p=>{const l=lotBy(state,p.lot);return (!filter||(l.species+' '+l.code+' '+p.location).toLowerCase().includes(filter.toLowerCase()))&&(!quality||l.quality===quality)&&(!nursery||p.nursery===nursery)&&(!status||p.status===status)});return heading('Inventario de plantas','Cada lote conserva su origen, calidad e historial.',button('Registrar alta','high','','primary'))+`<div class="filters"><input id="search" placeholder="Buscar especie, código o ubicación…" value="${h(filter)}" aria-label="Buscar inventario"><select id="quality-filter" aria-label="Calidad">${options(['','C1','C2','C3'],quality,'Todas las calidades')}</select><select id="nursery-filter" aria-label="Vivero">${options(['',...Object.keys(NURSERIES)],nursery,'Todos los viveros',NURSERIES)}</select><select id="status-filter" aria-label="Estado">${options(['','available','blocked','inspection','quarantine','transit','rejected'],status,'Todos los estados',stateLabels)}</select></div><section class="card"><div class="card-head"><h2>Existencias por lote y ubicación</h2><span class="search-count">${rows.length} registros</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Especie / lote</th><th>Calidad</th><th>Ubicación</th><th>Estado</th><th class="num">Plantas</th><th class="num">Asignadas</th><th></th></tr></thead><tbody>${rows.map(p=>{const l=lotBy(state,p.lot);return `<tr><td><b>${h(l.species)}</b><small>${h(l.code)}</small></td><td>${badge(l.quality,l.quality.toLowerCase())}</td><td>${h(NURSERIES[p.nursery]||'En tránsito')}<small>${h(p.location)}</small></td><td>${badge(p.status,p.status==='available'?'':p.status==='rejected'?'red':'warn')}</td><td class="num"><b>${num(p.qty)}</b></td><td class="num">${num(held(state,p.id))}</td><td>${button('Ver lote','lot',l.id,'small')}</td></tr>`}).join('')}</tbody></table></div>`:empty('No hay existencias para mostrar','Registra un alta o carga el escenario de ejemplo.',button('Registrar alta','high'))}</section><div class="note">Las reservas por especie se muestran en Pedidos. “Asignadas” indica cantidades ya vinculadas a una ubicación concreta. C3 también incluye plantas sanas recién establecidas.</div><div class="buttons">${button('Registrar movimiento','operation')}${button('Exportar inventario CSV','csv')}</div>`}
function orders(){return heading('Pedidos y despachos','Desde una solicitud visada hasta una entrega firmada.',button('Nuevo pedido','order','','primary'))+`<div class="order-grid">${state.orders.slice().reverse().map(o=>{const total=o.lines.reduce((a,l)=>a+l.qty,0),delivered=o.lines.reduce((a,l)=>a+l.delivered,0),assigned=o.allocations.reduce((a,l)=>a+l.qty,0);return `<article class="card order"><div class="order-top"><div><p class="eyebrow">${h(o.reference)}</p><h2>${h(o.company)}</h2></div>${badge(o.status,o.status==='pending'?'warn':'')}</div><div class="order-meta">${o.kind==='donation'?'Donación':h(o.contract)} · ${h(NURSERIES[o.nursery])}<br>Retiro: ${h(o.date||'Sin fecha')} · ${o.lines.length} líneas</div><div class="amount">${num(remaining(o))} <span style="font-size:12px;color:var(--muted)">plantas pendientes</span></div><small class="order-meta">${num(delivered)} entregadas · ${num(assigned)} asignadas a lotes</small><div class="progress"><i style="width:${total?delivered/total*100:0}%"></i></div>${o.shortage?.status==='pending'?'<div class="note warn">Faltante pendiente de resolución AdC MLP</div>':''}<div class="buttons">${button('Abrir pedido','orderDetail',o.id,'small primary')}${o.status==='pending'?button('Autorizar donación','approveDonation',o.id,'small'):''}</div></article>`}).join('')||`<section class="card wide">${empty('Tu primera solicitud aprobada','Ingresa su referencia y respaldo; luego reserva y asigna lotes.',button('Crear pedido','order'))}</section>`}</div><section class="card" style="margin-top:22px"><div class="card-head"><h2>Tickets emitidos</h2><span class="subtitle">58 mm · dos copias</span></div>${state.dispatches.length?`<div class="table-wrap"><table><thead><tr><th>Despacho</th><th>Destinatario</th><th>Fecha</th><th>Plantas</th><th></th></tr></thead><tbody>${state.dispatches.slice().reverse().map(t=>`<tr><td>${h(t.id.slice(0,12))}…<small>${h(t.reference)}</small></td><td>${h(t.company)}</td><td>${date(t.at)}</td><td>${num(t.total)}</td><td>${button('Ticket','ticket',t.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Aún no hay tickets','Se emiten después de capturar la firma y confirmar una entrega.')}</section>`}
function transfers(){return heading('Traslados entre viveros','La salida y cada recepción permanecen vinculadas.',button('Nuevo traslado','transfer','','primary'))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Traslado / lote</th><th>Recorrido</th><th>Enviadas</th><th>Pendientes</th><th>Estado</th><th></th></tr></thead><tbody>${state.transfers.map(t=>`<tr><td><b>${h(lotBy(state,t.lot).species)}</b><small>${h(t.id.slice(0,15))}…${t.returnOf?' · Retorno':''}</small></td><td>${h(NURSERIES[t.from])} → ${h(NURSERIES[t.to])}</td><td>${num(t.qty)}</td><td>${num(state.positions.find(p=>p.id===t.position)?.qty)}</td><td>${badge(t.status,'warn')}</td><td>${button('Registrar llegada','receive',t.id,'small')}</td></tr>`).join('')}</tbody></table></div>${!state.transfers.length?empty('Sin traslados registrados','Confirma una salida desde el vivero de origen para comenzar.'):''}</section><div class="note">Registrar la llegada no autoriza el ingreso. La partida queda bloqueada hasta la inspección ITO. Las diferencias permanecen en tránsito hasta una recepción posterior; el cierre por acuerdo o arbitraje está pendiente de implementación.</div>`}
function inspections(){const rows=state.positions.filter(p=>p.qty>0&&['inspection','quarantine','rejected','blocked'].includes(p.status));return heading('Inspección y calidad','Calidad, condición sanitaria y ubicación son independientes.',button('Cambio de calidad','quality','','primary'))+`<section class="card"><div class="card-head"><h2>Partidas bajo control</h2><span>${rows.length} pendientes</span></div><div class="table-wrap"><table><thead><tr><th>Especie / lote</th><th>Ubicación</th><th>Plantas</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${h(lotBy(state,p.lot).species)}</b><small>${h(lotBy(state,p.lot).code)}</small></td><td>${h(p.location)}</td><td>${num(p.qty)}</td><td>${badge(p.status,'warn')}</td><td><div class="buttons">${p.status==='inspection'?button('Evaluar ingreso','inspect',p.id,'small primary'):p.status==='quarantine'?button('Tratamiento','treatment',p.id,'small')+button('Liberar lote','releaseQuarantine',p.id,'small'):p.status==='blocked'?button('Evaluar / liberar','unblock',p.id,'small'):''}${['quarantine','rejected'].includes(p.status)?button('Retornar al origen','returnOrigin',p.id,'small'):''}</div></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Sin inspecciones pendientes','Las llegadas, cuarentenas y bloqueos aparecerán aquí.'):''}</section><div class="note">La liberación de cuarentena abarca el saldo completo de la partida recibida. Una evaluación de muestra no reclasifica porcentajes automáticamente: registre una reclasificación separada para cantidades verificadas.</div>`}
function returnsView(){return heading('Devoluciones de EECC','Recibir en custodia no significa aceptar la devolución.',button('Recibir devolución','returnReceive','','primary'))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Origen</th><th>Recibidas</th><th>Aceptadas</th><th>Rechazadas</th><th>Retiradas</th><th>Estado</th><th></th></tr></thead><tbody>${state.returns.map(r=>{const t=state.dispatches.find(t=>t.id===r.dispatch);return `<tr><td><b>${h(t.company)}</b><small>${h(t.details[r.detail].species)}</small></td><td>${num(r.qty)}</td><td>${num(r.accepted)}</td><td>${num(r.rejected)}</td><td>${num(r.collected)}</td><td>${badge(r.status,r.status==='closed'?'':'warn')}</td><td>${r.status==='pending'?button('Evaluar ITO','returnInspect',r.id,'small'):r.status==='rejected'?button('Registrar retiro','returnCollect',r.id,'small'):''}</td></tr>`}).join('')}</tbody></table></div>${!state.returns.length?empty('Sin devoluciones','Primero emite un despacho de prueba y crea una zona de custodia.'):''}</section><div class="note">Solo las C1 y C2 aceptadas vuelven al inventario. Las C3 rechazadas continúan en custodia hasta su retiro firmado. La reposición requiere una nueva solicitud.</div>`}
function locations(){return heading('Ubicaciones del vivero','Vivero, sector y mesón, platabanda o invernadero.',button('Nueva ubicación','location','','primary'))+`<div class="order-grid">${state.locations.map(l=>`<article class="card order"><div class="order-top"><div><p class="eyebrow">${h(NURSERIES[l.nursery])} / ${h(l.sector)}</p><h2>${h(l.kind)} ${h(l.name)}</h2></div>${icon('pin').replace('<svg ','<svg style="width:24px;height:24px" ')}</div><p class="order-meta">${h(l.id)}</p><div class="amount">${num(state.positions.filter(p=>p.location===l.id).reduce((n,p)=>n+p.qty,0))} <span class="order-meta">plantas físicas (incluye custodia)</span></div><div class="buttons">${button('Ver contenido','locationDetail',l.id,'small')}${button('Etiqueta QR','qr','location|'+l.id,'small')}${l.kind==='Cuarentena'&&!l.enabled?button('Habilitar ITO','enableQuarantine',l.id,'small'):''}</div></article>`).join('')}</div>`}
function history(){return heading('Historial auditable','Cada registro conserva fecha, responsable y efecto sobre las existencias.',button('Exportar respaldo','export'))+`<section class="card">${listEvents(state.events)}</section>`}
function settings(){return heading('Guía de pruebas','Una primera versión para aprender con ejemplos en Monte Aranda.',button('Exportar respaldo','export','','primary'))+`<div class="capabilities"><section class="card"><div class="card-head"><h2>Empieza por este recorrido</h2></div><div class="card-body"><ol style="padding-left:18px;line-height:2;font-size:13px"><li>Carga el escenario ficticio de ejemplo.</li><li>Abre Pedidos y elige SOL-DEMO-001.</li><li>Asigna lotes C1 para cada especie.</li><li>Registra receptor, firma y confirma la entrega.</li><li>Copia las dos versiones del ticket a POS-Printer.</li><li>Revisa los saldos y el historial.</li></ol><div class="buttons">${button('Cargar escenario','demo')}${button('Cambiar rol de prueba','profile')}</div></div></section><section class="card"><div class="card-head"><h2>Alcance de esta entrega</h2></div><div class="card-body"><ul><li>Operaciones locales con historial y controles de stock.</li><li>Roles simulados para ensayar autorizaciones.</li><li>Firmas y fotos guardadas en este navegador.</li><li>Respaldo JSON y exportación de inventario CSV.</li><li>Ticket de 58 mm y QR de lotes y ubicaciones.</li><li>Uso sin conexión después de cargar la app.</li></ul><div class="note warn"><b>No usar con datos reales todavía.</b> No hay autenticación, base compartida ni sincronización entre dispositivos. Cambiar de celular no transfiere los registros.</div></div></section><section class="card"><div class="card-head"><h2>Respaldo y continuidad</h2></div><div class="card-body"><p class="subtitle">Exporta al terminar la prueba. Borrar datos del navegador puede eliminar lotes, fotos y firmas. Restaurar reemplaza el ensayo local completo; no mezcla dispositivos.</p><div class="buttons" style="margin-top:18px">${button('Exportar JSON','export')}${button('Restaurar respaldo','import')}${button('Inventario CSV','csv')}</div><input type="file" id="restore-file" accept="application/json" hidden><div class="note">Instala desde el menú del navegador: “Añadir a pantalla de inicio”. En iPhone, utiliza Safari. La impresión se realiza copiando el texto en POS-Printer; la compatibilidad física debe probarse.</div></div></section><section class="card"><div class="card-head"><h2>Próxima iteración</h2></div><div class="card-body"><ul><li>Cuentas reales y permisos de servidor.</li><li>Base central y sincronización sin duplicidades.</li><li>Etiquetas A4 de seis unidades y verificación física de QR.</li><li>Pauta estructurada de mediciones por especie.</li><li>Cierre de diferencias con conformidad y arbitraje.</li><li>Ingreso C3 a tratamiento con autorización específica.</li></ul><div class="buttons">${button('Registrar observación','feedback')}${button('Reiniciar ensayo','reset','','danger')}</div></div></section></div><section class="card" style="margin-top:20px"><div class="card-head"><h2>Observaciones del ensayo</h2></div><div class="card-body">${state.feedback.map(f=>`<div class="task"><span><b>${h(f.area)} · ${h(f.message)}</b><small>${date(f.at)} · ${h(f.actor)}</small></span></div>`).join('')||'<p class="subtitle">Registra qué falta, qué sobra o qué resultó difícil. Se incluirá en tu respaldo.</p>'}</div></section>`}
function render(){const views={home,inventory,orders,transfers,inspections,returns:returnsView,locations,history,settings,scan:scanView};$('#app').innerHTML=shell(views[view]());bind();if(view==='scan')startScanner();}
function options(items,selected='',placeholder='',labels={}){return items.map(x=>typeof x==='object'?`<option value="${h(x.value)}" ${x.value===selected?'selected':''}>${h(x.label)}</option>`:`<option value="${h(x)}" ${x===selected?'selected':''}>${h(x===''?placeholder:labels[x]||x)}</option>`).join('')}
function field(name,label,type='text',value='',extra=''){return `<div class="field ${type==='textarea'||type==='file'?'full':''}"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${extra}>${h(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${h(value)}" ${extra}>`}</div>`}
function select(name,label,items,value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options(items,value)}</select></div>`}
function locationOptions(kind){return state.locations.filter(l=>!kind||kind(l)).map(l=>({value:l.id,label:NURSERIES[l.nursery]+' · '+l.sector+' · '+l.kind+' '+l.name}))}
function positionOptions(pred){return state.positions.filter(p=>p.qty>0&&(!pred||pred(p))).map(p=>({value:p.id,label:lotBy(state,p.lot).species+' '+lotBy(state,p.lot).quality+' · '+p.location+' · '+p.qty+' plantas'}))}
const reasonFields=()=>field('reason','Justificación / observación técnica','textarea','','required')+field('photos','Fotografías de prueba (obligatorias)','file','','accept="image/*" multiple required');
function modal(title,body,onSubmit,after){const dlg=$('#dialog');if(dlg.open)dlg.close();dlg.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" type="button" aria-label="Cerrar">×</button></div><div class="modal-body">${onSubmit?'<form id="form">':''}${body}${onSubmit?'<div class="error-box" role="alert"></div><div class="form-actions"><button class="button" type="button" id="cancel">Cancelar</button><button class="button primary" type="submit">Confirmar registro</button></div></form>':''}</div>`;dlg.showModal();dlg.querySelector('.close').onclick=()=>dlg.close();$('#cancel')?.addEventListener('click',()=>dlg.close());dlg.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));if(onSubmit)$('#form').onsubmit=async e=>{e.preventDefault();const submit=$('#form button[type=submit]');submit.disabled=true;$('.error-box').textContent='';try{const form=e.target;const d=Object.fromEntries(new FormData(form));if(form.photos){d.photos=await Promise.all([...form.photos.files].map(readImage));}await onSubmit(d);if(dlg.open)dlg.close();render()}catch(error){$('.error-box').textContent=error.message;submit.disabled=false}};after?.();}
function readImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('Seleccione fotografías.'));if(file.size>12*1024*1024)return reject(new Error('Cada imagen debe pesar menos de 12 MB.'));const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,1200/im.width,1200/im.height),c=document.createElement('canvas');c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.75))};im.onerror=()=>reject(new Error('No se pudo leer la imagen; use JPG o PNG.'));im.src=r.result};r.onerror=()=>reject(r.error);r.readAsDataURL(file)})}
async function command(type,data,id=uid()){state=await runCommand({id,type,data},actor);channel?.postMessage('updated');toast('Registro guardado en este dispositivo.');}
function operation(type='',pid=''){if(!type){modal('Registrar movimiento',`<p class="subtitle">Selecciona qué ocurrió. Cada cambio genera un registro.</p><div class="quick" style="margin-top:20px">${[['move','Ubicación'],['quality','Calidad (ITO)'],['container','Contenedor'],['loss','Mortalidad'],['adjust','Ajuste de conteo'],['block','Bloqueo preventivo']].map(([a,l])=>button(l,a)).join('')}</div>`);return}const title={move:'Mover dentro del vivero',quality:'Cambio de calidad · Supervisor ITO',container:'Cambio de contenedor',loss:'Baja por mortalidad',adjust:'Ajuste de inventario',block:'Bloqueo preventivo',unblock:'Liberar bloqueo · Supervisor ITO'}[type];let fields=select('position','Existencia de origen',positionOptions(p=>!['transit','custody'].includes(p.status)),pid)+field('qty',type==='adjust'?'Cantidad de diferencia':'Cantidad involucrada','number','', 'min="1" step="1" required');if(type==='move')fields+=select('location','Destino',locationOptions());if(type==='quality')fields+=select('quality','Calidad nueva',['C1','C2','C3']);if(type==='container')fields+=field('container','Nuevo código de contenedor','text','','required pattern="[A-Za-z0-9_]+"');if(type==='adjust')fields+=select('direction','Efecto',['subtract','add'].map(x=>({value:x,label:x==='add'?'Aumentar por conteo':'Disminuir por conteo'})));fields+=['quality','loss','adjust'].includes(type)?reasonFields():field('reason','Motivo','textarea','','required');modal(title,`<div class="note">${type==='quality'?'Requiere evaluación del estándar MLP. No se deduce la calidad automáticamente de una muestra.':'Las cantidades se validan contra el saldo y las asignaciones del pedido.'}</div><div class="form-grid">${fields}</div>`,d=>command(type,d));}
function high(){modal('Alta de plantas establecidas',`<div class="note">El primer conteo ingresa como C3. Las incorporaciones con igual código se agrupan en el mismo lote.</div><div class="form-grid">${field('species','Especie','text','','required placeholder="Ej.: Quillay"')}${field('speciesCode','Código de especie','text','','required placeholder="Ej.: QUI"')}${field('provenance','Código de procedencia','text','','required placeholder="Ej.: MLP"')}${field('sowing','Mes y año de siembra','month','','required')}${field('container','Código de contenedor','text','BOL','required')}${select('origin','Vivero de origen',Object.entries(NURSERIES).map(([v,l])=>({value:v,label:l})),actor.nursery)}${field('qty','Plantas contadas','number','','min="1" step="1" required')}${select('location','Ubicación inicial',locationOptions(l=>l.nursery===actor.nursery&&!['Custodia','Cuarentena'].includes(l.kind)))}</div>`,d=>command('high',d))}
let lineCounter=0;
function orderLine(){const id=++lineCounter;return `<div class="line-editor"><div class="line-top"><span>Especie / destino de uso</span><button class="text-link" type="button" data-remove-line>Quitar</button></div><div class="form-grid">${select('sp'+id,'Especie',[...new Set(state.lots.map(l=>l.species))],'','data-line="species"')}${select('qu'+id,'Calidad',['C1','C2','C3'],'C1','data-line="quality"')}${field('n'+id,'Cantidad','number','','data-line="qty" min="1" step="1" required')}${field('pr'+id,'Proyecto','text','','data-line="project"')}${field('co'+id,'Compromiso','text','','data-line="commitment"')}${select('us'+id,'Uso',['Plantación inicial','Mantención','Replante'],'','data-line="use"')}</div></div>`}
function orderForm(){modal('Incorporar pedido',`<div class="note">EECC: registra una solicitud ya visada. Donación: requiere autorización del rol AdC MLP dentro del piloto.</div><div class="form-grid">${select('kind','Tipo',[{value:'eecc',label:'Entrega a EECC'},{value:'donation',label:'Donación'}])}${field('reference','Referencia única de solicitud','text','','required')}${field('company','EECC / beneficiario','text','','required')}${field('contract','Contrato (EECC)','text')}${select('nursery','Vivero de entrega',Object.entries(NURSERIES).map(([v,l])=>({value:v,label:l})),actor.nursery)}${field('date','Fecha programada','date','','required')}${field('approval','Referencia del respaldo de aprobaciones / motivo de donación','textarea','','required')}</div><h3 style="margin-top:20px">Detalle por especie y compromiso</h3><div id="order-lines">${orderLine()}</div><button class="button" type="button" id="add-line">+ Agregar otra especie / compromiso</button>`,d=>{d.lines=$$('#order-lines .line-editor').map(el=>Object.fromEntries([...el.querySelectorAll('[data-line]')].map(x=>[x.dataset.line,x.value])));return command('order',d)},()=>{$('#add-line').onclick=()=>{$('#order-lines').insertAdjacentHTML('beforeend',orderLine());bindLines()};bindLines()})}
function bindLines(){$$('[data-remove-line]').forEach(b=>b.onclick=()=>b.closest('.line-editor').remove())}
function orderDetail(id){const o=state.orders.find(x=>x.id===id);modal('Pedido '+h(o.reference),`<p><b>${h(o.company)}</b> · ${h(o.contract||'Donación')} ${badge(o.status)}</p><p class="subtitle">Respaldo: ${h(o.approval)}</p><div class="table-wrap"><table><thead><tr><th>Especie / compromiso</th><th>Solicitadas</th><th>Entregadas</th><th>Pendientes</th><th></th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${h(l.species)} ${badge(l.quality)}<small>${h(l.project)} / ${h(l.commitment)} / ${h(l.use)}</small></td><td>${num(l.qty)}</td><td>${num(l.delivered)}</td><td>${num(l.qty-l.delivered-l.released)}</td><td>${o.status==='approved'?button('Asignar lote','allocate',o.id+'|'+l.id,'small'):''}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:20px">Lotes preparados</h3>${o.allocations.map(a=>{const p=state.positions.find(p=>p.id===a.position),l=lotBy(state,p.lot);return `<div class="task"><span><b>${h(l.species)} · ${num(a.qty)} plantas</b><small>${h(l.code)} / ${h(p.location)}</small></span>${button('Sustituir','releaseAllocation',o.id+'|'+a.id,'small')}</div>`}).join('')||'<p class="subtitle">Aún no hay lotes asignados.</p>'}<div class="buttons" style="margin-top:20px">${o.status==='approved'?button('Firmar y entregar','dispatch',o.id,'primary')+button('Reprogramar','reschedule',o.id)+button('Liberar por no retiro','releaseReservation',o.id)+button('Evaluar faltante ITO','shortageReview',o.id):''}${o.shortage?.status==='pending'?button('Resolver AdC MLP','shortageResolve',o.id):''}</div>`)}
function allocate(args){const [order,line]=args.split('|'),o=state.orders.find(o=>o.id===order),l=o.lines.find(l=>l.id===line);modal('Asignar lote · '+h(l.species),`<div class="form-grid">${select('position','Existencia disponible',positionOptions(p=>p.nursery===o.nursery&&p.status==='available'&&lotBy(state,p.lot).species===l.species&&lotBy(state,p.lot).quality===l.quality))}${field('qty','Cantidad a preparar','number','','min="1" required')}</div>`,d=>command('allocate',{...d,order,line}))}
function signatureUI(){return `<h3 style="margin-top:20px">Firma del receptor</h3><p class="subtitle">Revise el detalle antes de firmar. Firma de prueba, guardada solo en este dispositivo.</p><canvas class="signature" id="signature" width="900" height="300" aria-label="Área de firma"></canvas><button type="button" class="text-link" id="clear-signature">Borrar firma</button><label class="check-label"><input type="checkbox" name="signed" required>Confirmo que el receptor revisó las cantidades y firmó esta entrega.</label>`}
let hasSignature=false;
function setupSignature(){hasSignature=false;const c=$('#signature'),ctx=c.getContext('2d');let drawing=false;ctx.lineWidth=3;ctx.lineCap='round';ctx.strokeStyle='#183e34';const point=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};c.onpointerdown=e=>{drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e))};c.onpointermove=e=>{if(!drawing)return;ctx.lineTo(...point(e));ctx.stroke();hasSignature=true};c.onpointerup=()=>drawing=false;c.onpointercancel=()=>drawing=false;$('#clear-signature').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);hasSignature=false};}
function dispatchForm(id){const o=state.orders.find(o=>o.id===id);const cid=uid();modal('Confirmar entrega · '+h(o.reference),`<p><b>${h(o.company)}</b> · ${h(o.contract||'Donación')}</p><div class="note">Entrega de prueba. Solo se descuentan las cantidades indicadas y firmadas. Cero permite dejar una línea pendiente.</div><div class="table-wrap"><table><thead><tr><th>Especie / lote / compromiso</th><th>A entregar</th></tr></thead><tbody>${o.allocations.map(a=>{const p=state.positions.find(p=>p.id===a.position),l=lotBy(state,p.lot),line=o.lines.find(l=>l.id===a.line);return `<tr><td>${h(l.species)} ${badge(l.quality)}<small>${h(l.code)}<br>${h(line.commitment)} · ${h(line.use)}</small></td><td><input type="number" min="0" max="${a.qty}" step="1" value="${a.qty}" data-delivery="${a.id}" aria-label="Cantidad ${h(l.species)}" style="width:100px"></td></tr>`}).join('')}</tbody></table></div><div class="form-grid" style="margin-top:18px">${field('receiver','Nombre de quien recibe','text','','required')}${field('job','Cargo del receptor','text','','required')}${field('driver','Chofer','text','','required')}${field('plate','Patente','text','','required')}</div>${signatureUI()}`,async d=>{if(!hasSignature)throw new Error('El receptor debe firmar antes de confirmar.');const items=$$('[data-delivery]').map(x=>({allocation:x.dataset.delivery,qty:x.value}));await command('dispatch',{...d,order:id,items,signature:$('#signature').toDataURL(),signed:true},cid);setTimeout(()=>ticket(state.dispatches.at(-1).id),0)},()=>{setupSignature();$$('[data-delivery],#f-receiver,#f-job,#f-driver,#f-plate').forEach(el=>el.addEventListener('input',()=>{$('#clear-signature').click();$('#form [name=signed]').checked=false}))})}
function ticket(id){const t=state.dispatches.find(t=>t.id===id);const copy=t.kind==='donation'?'BENEFICIARIO':'EECC';modal('Ticket de despacho · 58 mm',`<p class="subtitle">Mismo número en ambas copias. Reimprimir no modifica inventario.</p><div class="buttons">${button('Copiar '+copy,'copyTicket',id+'|'+copy)}${button('Copiar VMA','copyTicket',id+'|VMA')}${button('Imprimir / PDF','printTicket',id)}${button('Ver firma guardada','viewSignature',id)}</div><pre class="ticket">${h(ticketText(t,state,copy))}</pre><div class="note">Pega el texto en POS-Printer. Conserva el mismo ID al reimprimir. La firma no se imprime; su imagen queda en el respaldo local.</div>`)}
function transferForm(){modal('Confirmar salida a otro vivero',`<div class="form-grid">${select('position','Lote de origen',positionOptions(p=>p.status==='available'&&p.nursery===actor.nursery))}${field('qty','Cantidad a trasladar','number','','min="1" required')}${select('destination','Vivero destino',Object.entries(NURSERIES).filter(([id])=>id!==actor.nursery).map(([value,label])=>({value,label})))}</div><div class="note">La cantidad pasa a tránsito; no disminuye el inventario general.</div>`,d=>command('transfer',d))}
function inspectForm(id){const p=state.positions.find(p=>p.id===id);modal('Inspección de ingreso · ITO',`<p>${h(lotBy(state,p.lot).species)} · ${num(p.qty)} plantas</p><div class="form-grid">${field('sample','Plantas evaluadas en la muestra','number','','min="1" required')}${select('decision','Resolución',[{value:'accept',label:'Autorizar ingreso sin problema sanitario'},{value:'reject',label:'Rechazar lote completo por sanidad'},{value:'quarantine',label:'Ingreso excepcional a cuarentena'}])}${select('quality','Calidad verificada para esta partida',['C1','C2','C3'],lotBy(state,p.lot).quality)}${select('location','Zona de cuarentena (solo si corresponde)',[{value:'',label:'No aplica'},...locationOptions(l=>l.kind==='Cuarentena'&&l.enabled&&l.nursery===p.nursery)])}${field('measurements','Resultados: altura, DAC, raíces, follaje, muestra C1/C2/C3 y pauta utilizada','textarea','','required')}${reasonFields()}</div><label class="check-label"><input name="healthy" type="checkbox">Evaluación favorable: sin plagas ni enfermedades detectadas.</label><div class="note">Autorizar con otra calidad reclasifica la partida completa. Para resultados mixtos, conserve la calidad y registre después cambios por cantidades verificadas.</div>`,d=>command('inspect',{...d,position:id,healthy:!!d.healthy}))}
function returnReceiveForm(){modal('Recibir devolución en custodia',`<div class="form-grid">${select('dispatch','Despacho original',state.dispatches.filter(t=>t.nursery===actor.nursery).map(t=>({value:t.id,label:t.reference+' · '+t.company})))}<div class="field"><label for="return-detail">Línea del despacho</label><select id="return-detail" name="detail"></select></div>${field('qty','Cantidad físicamente recibida','number','','min="1" required')}${select('location','Zona exclusiva de custodia',locationOptions(l=>l.kind==='Custodia'&&l.nursery===actor.nursery))}${field('reason','Motivo de devolución','textarea','','required')}</div><div class="note">La cantidad queda fuera del inventario aceptado hasta la resolución ITO.</div>`,d=>command('returnReceive',d),()=>{const update=()=>{const t=state.dispatches.find(t=>t.id===$('#f-dispatch').value);$('#return-detail').innerHTML=options(t?t.details.map((l,i)=>({value:String(i),label:l.species+' · '+l.code+' · '+l.qty+' entregadas'})):[])};$('#f-dispatch').onchange=update;update()})}
async function action(type,id=''){
 try{
 if(['move','quality','container','loss','adjust','block','unblock','operation'].includes(type))return operation(type==='operation'?'':type,id);
 if(type==='high')return high();if(type==='order')return orderForm();if(type==='orderDetail')return orderDetail(id);if(type==='allocate')return allocate(id);if(type==='dispatch')return dispatchForm(id);if(type==='ticket')return ticket(id);if(type==='transfer')return transferForm();if(type==='inspect')return inspectForm(id);if(type==='returnReceive')return returnReceiveForm();
 if(type==='menu'){$('.shell').classList.toggle('menu-open');return}
 if(type==='qr'){return qrModal(id)}
 if(type==='guide'){nav('settings');return}
 if(type==='profile'){modal('Responsable de prueba',`<div class="note warn">Este selector simula roles; no es una autenticación. Utiliza nombres ficticios en el piloto.</div><div class="form-grid">${field('name','Nombre para el historial','text',actor.name,'required')}${select('role','Rol a ensayar',ROLES,actor.role)}${select('nursery','Vivero a cargo',Object.entries(NURSERIES).map(([value,label])=>({value,label})),actor.nursery)}</div>`,async d=>{actor=d;localStorage.setItem('sitrap21-actor',JSON.stringify(actor));toast('Rol de prueba actualizado.');});return}
 if(type==='location'){modal('Crear ubicación',`<div class="form-grid">${select('nursery','Vivero',Object.entries(NURSERIES).map(([value,label])=>({value,label})),actor.nursery)}${field('sector','Sector','text','','required')}${select('kind','Tipo',['Mesón','Platabanda','Invernadero','Cuarentena','Tratamiento','Custodia'])}${field('name','Identificación','text','','required placeholder="Ej.: M02"')}</div>`,d=>command('location',d));return}
 if(type==='enableQuarantine'){modal('Habilitación de cuarentena · ITO',field('reason','Antecedente de habilitación del sector','textarea','','required'),d=>command(type,{...d,location:id}));return}
 if(type==='receive'){const t=state.transfers.find(t=>t.id===id);modal('Registrar llegada a '+h(NURSERIES[t.to]),`<div class="form-grid">${field('qty','Cantidad llegada','number','','min="1" required')}${select('location','Ubicación de evaluación',locationOptions(l=>l.nursery===t.to&&!['Cuarentena','Custodia'].includes(l.kind)))}</div><div class="note">La llegada queda pendiente de inspección ITO y bloqueada. El saldo no recibido permanece en tránsito.</div>`,d=>command(type,{...d,transfer:id}));return}
 if(type==='treatment'||type==='releaseQuarantine'){modal(type==='treatment'?'Registrar tratamiento':'Liberar cuarentena completa',`<div class="form-grid">${type==='treatment'?field('treatment','Tratamiento aplicado, producto, dosis utilizada y ejecutor','textarea','','required'):''}${reasonFields()}</div>${type==='releaseQuarantine'?'<label class="check-label"><input type="checkbox" name="healthy" required>Apruebo la liberación sanitaria de todo el saldo del lote en esta partida.</label>':''}`,d=>command(type,{...d,position:id,healthy:!!d.healthy}));return}
 if(type==='returnOrigin'){modal('Retornar lote rechazado',`<p>Se generará un traslado de retorno por la totalidad del saldo. La recepción deberá registrarse en el vivero de origen.</p>${field('reason','Motivo / resolución','textarea','','required')}`,d=>command(type,{...d,position:id}));return}
 if(type==='approveDonation'){modal('Autorizar donación · AdC MLP','<p>La autorización reserva las cantidades solicitadas. La salida de inventario ocurre únicamente con la entrega firmada.</p>',()=>command(type,{order:id}));return}
 if(type==='releaseAllocation'){const [order,allocation]=id.split('|');modal('Sustituir asignación',field('reason','Motivo de sustitución','textarea','','required')+'<div class="note">La reserva se conserva. Luego deberá asignar otro lote habilitado.</div>',d=>command(type,{...d,order,allocation}));return}
 if(['reschedule','releaseReservation','shortageReview','shortageResolve'].includes(type)){const title={reschedule:'Reprogramar retiro',releaseReservation:'Liberar reserva por no retiro',shortageReview:'Evaluar faltante · ITO',shortageResolve:'Resolver faltante · AdC MLP'}[type];modal(title,`<div class="form-grid">${type==='shortageResolve'?select('action','Resolución',[{value:'reschedule',label:'Reprogramar saldo'},{value:'close',label:'Reducir pedido a lo ya entregado'}]):''}${['reschedule','shortageResolve'].includes(type)?field('date','Nueva fecha (para reprogramación)','date'):''}${field('reason','Justificación','textarea','','required')}</div>${type==='releaseReservation'?'<div class="note warn">Solo para inasistencia o retiro cancelado. Un faltante de plantas debe evaluarlo el ITO y resolverlo la AdC MLP.</div>':''}`,d=>command(type,{...d,order:id}));return}
 if(type==='returnInspect'){const r=state.returns.find(r=>r.id===id);modal('Evaluación de devolución · ITO',`<p>Total en custodia: <b>${num(r.qty)}</b> plantas.</p><div class="form-grid">${field('c1','Aceptadas C1','number','0','min="0" required')}${field('c2','Aceptadas C2','number','0','min="0" required')}${field('c3','Rechazadas C3 / condición sanitaria','number','0','min="0" required')}${select('location','Ubicación de aceptadas',locationOptions(l=>l.nursery===state.positions.find(p=>p.id===r.position).nursery&&!['Custodia','Cuarentena'].includes(l.kind)))}${reasonFields()}</div><div class="note">No se genera reposición ni reserva automática. Las rechazadas permanecen en custodia.</div>`,d=>command(type,{...d,return:id}));return}
 if(type==='returnCollect'){modal('Retiro de plantas rechazadas',`<div class="form-grid">${field('qty','Cantidad retirada','number','','min="1" required')}${field('receiver','Nombre receptor EECC','text','','required')}</div>${signatureUI()}`,d=>{if(!hasSignature)throw new Error('Firma obligatoria.');return command(type,{...d,return:id,signature:$('#signature').toDataURL(),signed:true})},()=>{setupSignature();$$('#f-qty,#f-receiver').forEach(el=>el.oninput=()=>{$('#clear-signature').click();$('#form [name=signed]').checked=false})});return}
 if(type==='lot'){const l=lotBy(state,id);const p=state.positions.filter(p=>p.lot===id&&p.qty);const events=state.events.filter(e=>[e.payload.lot,e.payload.fromLot,e.payload.toLot].includes(id)||e.entries.some(en=>state.positions.some(p=>p.id===en.position&&p.lot===id)));modal(h(l.species)+' · '+l.quality,`<p><b>${h(l.code)}</b></p><p class="subtitle">Procedencia ${h(l.provenance)} · Siembra ${h(l.sowing)} · Contenedor ${h(l.container)} · Origen ${h(NURSERIES[l.origin])}</p><div class="status-list">${p.map(p=>`<div><span>${h(p.location)} ${badge(p.status)}</span><b>${num(p.qty)}</b></div>`).join('')}</div><div class="buttons" style="margin-top:16px">${button('Etiqueta QR','qr','lot|'+id)}</div><h3 style="margin-top:20px">Historial del lote</h3>${listEvents(events)}`);return}
 if(type==='locationDetail'){const l=locBy(state,id);modal(h(l.id),`<p>${h(NURSERIES[l.nursery])} · ${h(l.sector)} · ${h(l.kind)} ${h(l.name)}</p><div class="status-list">${state.positions.filter(p=>p.location===id&&p.qty).map(p=>`<div><span>${h(lotBy(state,p.lot).species)} ${badge(lotBy(state,p.lot).quality)} ${badge(p.status)}</span><b>${num(p.qty)}</b></div>`).join('')||'<p>Ubicación sin plantas.</p>'}</div><div class="note">El QR permite abrir esta ubicación en un dispositivo que tenga los mismos datos de prueba.</div>`);return}
 if(type==='event'){const e=state.events.find(e=>e.id===id);modal(h(e.type),`<p>${date(e.at)} · ${h(e.actor)} · ${h(e.role)}</p><div class="status-list">${Object.entries(e.payload).filter(([k,v])=>!['photos','signature'].includes(k)&&typeof v!=='object').map(([k,v])=>`<div><span>${h(k)}</span><b style="max-width:70%;overflow-wrap:anywhere">${h(v)}</b></div>`).join('')}</div><div class="photos">${(e.payload.photos||[]).filter(p=>p.startsWith('data:image/')).map(p=>`<img src="${h(p)}" alt="Respaldo de la operación">`).join('')}</div>${e.payload.signature?`<img src="${h(e.payload.signature)}" alt="Firma guardada" style="max-width:100%">`:''}<p class="subtitle">Identificador de operación: ${h(e.commandId)}</p>`);return}
 if(type==='viewSignature'){const t=state.dispatches.find(t=>t.id===id);modal('Firma de recepción',`<p>${h(t.receiver)} · ${h(t.company)}</p><img src="${h(t.signature)}" alt="Firma del receptor" style="width:100%;border:1px solid #ddd"><p class="subtitle">${date(t.at)} · Firma local de prueba vinculada a ${h(t.id)}</p>`);return}
 if(type==='copyTicket'){const [tid,copy]=id.split('|'),text=ticketText(state.dispatches.find(t=>t.id===tid),state,copy);try{await navigator.clipboard.writeText(text);toast('Ticket copiado. Pégalo en POS-Printer.')}catch{modal('Copiar manualmente',`<p>Selecciona y copia este texto para POS-Printer.</p><textarea style="height:350px">${h(text)}</textarea>`)}return}
 if(type==='printTicket'){const t=state.dispatches.find(t=>t.id===id);$('#print-area').innerHTML=[t.kind==='donation'?'BENEFICIARIO':'EECC','VMA'].map(copy=>`<pre class="ticket">${h(ticketText(t,state,copy))}</pre>`).join('');window.print();return}
 if(type==='export'){download('SITRAP-2.1-respaldo-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');toast('Respaldo exportado: incluye firmas y fotografías.');return}
 if(type==='csv'){const rows=[['ID_Lote_SITRAP','Especie','Calidad','Vivero','Ubicacion','Estado','Cantidad']];state.positions.filter(p=>p.qty>0).forEach(p=>{const l=lotBy(state,p.lot);rows.push([l.code,l.species,l.quality,p.nursery,p.location,p.status,p.qty])});download('SITRAP-2.1-inventario.csv','\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(';')).join('\n'),'text/csv');return}
 if(type==='import'){$('#restore-file').click();return}
 if(type==='demo'||type==='reset'){modal(type==='demo'?'Cargar escenario ficticio':'Reiniciar ensayo',`<p>${type==='demo'?'Se cargarán seis especies, existencias en VMA y Quillota y un pedido de ejemplo.':'El ensayo quedará sin lotes, pedidos ni movimientos.'}</p><div class="note warn">Se reemplazarán todos los registros locales. Exporta un respaldo antes de continuar.</div>${field('confirm','Escribe REEMPLAZAR para continuar','text','','required pattern="REEMPLAZAR"')}`,async()=>{await replaceState(type==='demo'?demoState():emptyState(),state.revision);state=await readState();channel?.postMessage('updated');toast(type==='demo'?'Escenario cargado. Abre Pedidos para practicar.':'Ensayo reiniciado.')});return}
 if(type==='feedback'){modal('Registrar observación de prueba',`<div class="form-grid">${select('area','Módulo',menus.map(x=>x[2]))}${field('message','Qué ocurrió / qué mejorar','textarea','','required')}</div>`,d=>command('feedback',d));return}
 }catch(e){toast(e.message)}
}
function download(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){$$('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));const search=$('#search');if(search)search.oninput=()=>{const start=search.selectionStart;filter=search.value;render();$('#search').focus();$('#search').setSelectionRange(start,start)};for(const [sel,set] of [['#quality-filter',v=>quality=v],['#nursery-filter',v=>nursery=v],['#status-filter',v=>status=v]])if($(sel))$(sel).onchange=e=>{set(e.target.value);render()};if($('#restore-file'))$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const incoming=JSON.parse(await f.text());modal('Restaurar respaldo','<p>Esto reemplazará el ensayo local por el archivo seleccionado. No combina datos de varios dispositivos.</p>'+field('confirm','Escribe RESTAURAR','text','','required pattern="RESTAURAR"'),async()=>{await replaceState(incoming,state.revision);state=await readState();channel?.postMessage('updated');toast('Respaldo restaurado.')})}catch(error){toast('Archivo no válido: '+error.message)}}}
try{state=await openStore();channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('sitrap21'):null;if(channel)channel.onmessage=async()=>{if(!$('#dialog').open){state=await readState();render()}else toast('Cambios en otra pestaña; se validarán al confirmar.')};render();const q=new URLSearchParams(location.search);if(q.has('lot')&&state.lots.some(l=>l.id===q.get('lot')))action('lot',q.get('lot'));else if(q.has('location')&&state.locations.some(l=>l.id===q.get('location')))action('locationDetail',q.get('location'));else if(q.has('lot')||q.has('location'))toast('Este QR no tiene datos en este dispositivo. Restaura el respaldo del ensayo correspondiente.');if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('No se pudo preparar el modo sin conexión.'));window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());}catch(e){$('#app').innerHTML=`<div class="loading"><h1>No se pudo abrir el almacenamiento local</h1><p>${h(e.message)}</p><p>Prueba un navegador normal (no privado) con almacenamiento disponible. No se han descartado datos.</p></div>`}

function qrModal(value){const [type,id]=value.split('|');const item=type==='lot'?lotBy(state,id):locBy(state,id);const url=new URL('./',location.href);url.searchParams.set(type,id);const qr=window.qrcode(0,'M');qr.addData(url.href);qr.make();const svg=qr.createSvgTag({cellSize:3,margin:10,scalable:true});modal('Etiqueta QR · '+(type==='lot'?'Lote':'Ubicación'),`<div style="max-width:270px;margin:auto;text-align:center">${svg}<h3>${h(type==='lot'?item.species:item.kind+' '+item.name)}</h3><p style="overflow-wrap:anywhere">${h(item.code||item.id)}</p></div><div class="note">El QR conserva el identificador. En este piloto solo abre datos disponibles en el dispositivo o restaurados desde su respaldo.</div><div class="buttons"><button class="button primary" id="download-qr">Descargar etiqueta SVG</button></div>`);$('#download-qr').onclick=()=>download('SITRAP-QR-'+(item.code||item.id)+'.svg',svg,'image/svg+xml');}
function scanView(){return heading('Escanear QR','Consulta un lote o una ubicación sin registrar movimientos automáticamente.')+`<section class="card"><div class="card-body" style="padding-top:22px"><div id="reader" style="max-width:550px;margin:auto"></div><div class="note">Permite el acceso a cámara. También puedes seleccionar una imagen QR del dispositivo. Solo se aceptan enlaces del mismo piloto.</div></div></section>`;}
function startScanner(){if(!window.Html5QrcodeScanner)return;scanner=new Html5QrcodeScanner('reader',{fps:10,qrbox:240},false);scanner.render(text=>{try{const u=new URL(text);if(u.origin!==location.origin||u.pathname!==new URL('./',location.href).pathname)throw new Error('QR externo: no se abrirá automáticamente.');const lot=u.searchParams.get('lot'),loc=u.searchParams.get('location');if(lot&&state.lots.some(l=>l.id===lot)){nav('inventory');action('lot',lot)}else if(loc&&state.locations.some(l=>l.id===loc)){nav('locations');action('locationDetail',loc)}else toast('Registro no encontrado en este dispositivo.')}catch(e){toast(e.message)}},()=>{});}
